def lookup(topic=None, query=None):
    rows = CITATIONS
    if topic:
        rows = [c for c in rows if topic.lower() in c["topic"].lower()]
    if query:
        q = query.lower()
        rows = [c for c in rows if q in (c["cite"] + c["finding"] + c["topic"]).lower()]
    return rows
